    private void btnInstruccionActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnInstruccionActionPerformed
        // Crear la ventana principal y reemplazar su contenido con el panel de Instrucciones
    FrJuego juego = new FrJuego();
    juego.getContentPane().removeAll();
    juego.add(new PanInstruccion());
    juego.revalidate();
    juego.repaint();
    juego.setVisible(true);

    // Cerrar el menu actual
    this.dispose();
    }//GEN-LAST:event_btnInstruccionActionPerformed

